"""DynamoDB client for recommendations generated by the Learning Agent."""

import os
import uuid
import logging
from datetime import datetime, timezone
from typing import Optional

import boto3
from boto3.dynamodb.conditions import Key
from tools.resource_names import table_name
from tools.aws.ddb_pages import read_all

logger = logging.getLogger("recommendations-client")


class RecommendationsRegistry:
    """CRUD operations for recommendations in DynamoDB."""

    def __init__(self):
        self._table = None

    @property
    def table(self):
        if self._table is None:
            from botocore.config import Config
            dynamodb = boto3.resource(
                "dynamodb",
                region_name=os.getenv("AWS_REGION", "us-east-1"),
                config=Config(max_pool_connections=50, retries={"max_attempts": 3, "mode": "adaptive"}),
            )
            self._table = dynamodb.Table(
                table_name("recommendations")
            )
        return self._table

    def create(self, data: dict) -> dict:
        """Create a new recommendation."""
        now = datetime.now(timezone.utc).isoformat()
        item = {
            "recommendation_id": str(uuid.uuid4()),
            "instance_id": data["instance_id"],
            "space_id": data.get("space_id", ""),
            "category": data.get("category", "performance"),
            "priority": data.get("priority", "medium"),
            "title": data["title"],
            "detail": data.get("detail", ""),
            "action": data.get("action", ""),
            "source_url": data.get("source_url", ""),
            "metric_key": data.get("metric_key", ""),
            "metric_trend": data.get("metric_trend", []),
            "finding_key": data.get("finding_key", ""),
            "finding_recurrence": data.get("finding_recurrence", 1),
            "status": "open",
            "created_at": now,
            "updated_at": now,
            "scan_date": data.get("scan_date", now[:10]),
        }
        # Strip None values for DynamoDB
        item = {k: v for k, v in item.items() if v is not None}
        self.table.put_item(Item=item)
        return item

    def get(self, recommendation_id: str) -> Optional[dict]:
        """Get a single recommendation."""
        response = self.table.get_item(Key={"recommendation_id": recommendation_id})
        return response.get("Item")

    def list_for_instance(self, instance_id: str) -> list:
        """List all recommendations for a database instance."""
        try:
            items = read_all(self.table.query, IndexName="instance-index",
                             KeyConditionExpression=Key("instance_id").eq(instance_id))
        except Exception:
            items = read_all(self.table.scan, FilterExpression="instance_id = :iid",
                             ExpressionAttributeValues={":iid": instance_id})
        items.sort(key=lambda x: x.get("created_at", ""), reverse=True)
        return items

    def list_for_space(self, space_id: str, status: Optional[str] = None) -> list:
        """List all recommendations for a space, optionally filtered by status."""
        try:
            items = read_all(self.table.query, IndexName="space-index",
                             KeyConditionExpression=Key("space_id").eq(space_id))
        except Exception:
            items = read_all(self.table.scan, FilterExpression="space_id = :sid",
                             ExpressionAttributeValues={":sid": space_id})
        if status:
            items = [i for i in items if i.get("status") == status]
        # Sort: open first, then by priority
        priority_order = {"critical": 0, "high": 1, "medium": 2, "low": 3}
        items.sort(key=lambda x: (
            0 if x.get("status") == "open" else 1,
            priority_order.get(x.get("priority", "medium"), 2),
            x.get("created_at", ""),
        ))
        return items

    def update_status(self, recommendation_id: str, status: str,
                      changed_by: str = "") -> Optional[dict]:
        """Update recommendation status."""
        now = datetime.now(timezone.utc).isoformat()
        expr = "SET #status = :status, updated_at = :now, status_changed_at = :now"
        vals = {":status": status, ":now": now}
        names = {"#status": "status"}
        if changed_by:
            expr += ", status_changed_by = :by"
            vals[":by"] = changed_by
        if status == "resolved":
            expr += ", resolved_at = :now"
        self.table.update_item(
            Key={"recommendation_id": recommendation_id},
            UpdateExpression=expr,
            ExpressionAttributeNames=names,
            ExpressionAttributeValues=vals,
        )
        return self.get(recommendation_id)

    def auto_resolve_for_instance(self, instance_id: str, current_finding_keys: set) -> int:
        """Auto-resolve recommendations whose findings no longer appear in the latest scan."""
        items = self.list_for_instance(instance_id)
        resolved = 0
        for item in items:
            if item.get("status") in ("open", "acknowledged", "in_progress"):
                fk = item.get("finding_key", "")
                if fk and fk not in current_finding_keys:
                    self.update_status(item["recommendation_id"], "resolved", "system-auto")
                    resolved += 1
        return resolved

    def delete(self, recommendation_id: str) -> bool:
        """Delete a recommendation."""
        self.table.delete_item(Key={"recommendation_id": recommendation_id})
        return True


recommendations_registry = RecommendationsRegistry()
